/** Msg defines the Msg service. */
export interface Msg {
  /** UserRequestGuardians defines Phase 1 of the three-phase commit protocol */
  UserRequestGuardians(request: MsgUserRequestGuardians): Promise<MsgUserRequestGuardiansResponse>;
  /** UserDistributeShares defines Phase 2 of the three-phase commit protocol */
  UserDistributeShares(request: MsgUserDistributeShares): Promise<MsgUserDistributeSharesResponse>;
  /** GuardianConfirmShares defines Phase 3 of the three-phase commit protocol */
  GuardianConfirmShares(request: MsgGuardianConfirmShares): Promise<MsgGuardianConfirmSharesResponse>;
  /** UserCancelSecret defines the UserCancelSecret RPC. */
  UserCancelSecret(request: MsgUserCancelSecret): Promise<MsgUserCancelSecretResponse>;
  /** GuardianRevealShare defines the GuardianRevealShare RPC for guardians to submit shares. */
  GuardianRevealShare(request: MsgGuardianRevealShare): Promise<MsgGuardianRevealShareResponse>;
  /** GuardianRegister defines the GuardianRegister RPC. */
  GuardianRegister(request: MsgGuardianRegister): Promise<MsgGuardianRegisterResponse>;
  /** GuardianUpdate defines the GuardianUpdate RPC. */
  GuardianUpdate(request: MsgGuardianUpdate): Promise<MsgGuardianUpdateResponse>;
  /**
   * GuardianRotateKey rotates the guardian's share-encryption key forward
   * for future assignments (appends the next key epoch).
   */
  GuardianRotateKey(request: MsgGuardianRotateKey): Promise<MsgGuardianRotateKeyResponse>;
  /** SlashGuardian defines the SlashGuardian RPC. */
  SlashGuardian(request: MsgSlashGuardian): Promise<MsgSlashGuardianResponse>;
  /** GuardianWithdrawStake defines the GuardianWithdrawStake RPC. */
  GuardianWithdrawStake(request: MsgGuardianWithdrawStake): Promise<MsgGuardianWithdrawStakeResponse>;
  /**
   * RecipientCommitRebate publishes the commitment that binds a recipiency
   * proof to the address collecting with it (step 1 of 2).
   */
  RecipientCommitRebate(request: MsgRecipientCommitRebate): Promise<MsgRecipientCommitRebateResponse>;
  /**
   * RecipientCollectRebate reveals the recipiency proof and pays the rebate to
   * the address that committed to it in an earlier block (step 2 of 2).
   */
  RecipientCollectRebate(request: MsgRecipientCollectRebate): Promise<MsgRecipientCollectRebateResponse>;
}

